/* بيانات قسم hadarat: تُحمَّل عند أول فتح للقسم */
window.HADARAT = {"k":[{"id":"nuh","t":"قوم نوح","d":"أول رسول إلى أهل الأرض بحسب ابن كثير؛ لبث فيهم ألف سنة إلا خمسين عاماً (العنكبوت: ١٤).","r":[11,25],"o":"عاقبتهم: الطوفان، ونجاة أصحاب السفينة."},{"id":"ad","t":"عاد","d":"إرم ذات العماد، سكنوا الأحقاف باليمن بحسب ابن كثير والسعدي، وجاؤوا خلفاء من بعد قوم نوح.","r":[89,6],"o":"عاقبتهم: ريح صرصر عاتية سبع ليالٍ وثمانية أيام."},{"id":"thamud","t":"ثمود","d":"بعد عاد، ومساكنهم بين الحجاز والشام إلى وادي القرى، وهم أصحاب الحِجر (ابن كثير).","r":[7,74],"o":"عاقبتهم: الصيحة والرجفة بعد عقر الناقة."},{"id":"lut","t":"قوم لوط","d":"أهل «سدوم» وما حولها من القرى في الشام، في زمن إبراهيم عليه السلام (ابن كثير).","r":[7,80],"o":"عاقبتهم: قُلبت قراهم وأُمطروا بحجارة من سجّيل."},{"id":"madyan","t":"أصحاب مدين والأيكة","d":"قبيلة معروفة بمدين، ونبيهم شعيب؛ وأصحاب الأيكة هم أهل مدين على الصحيح (ابن كثير).","r":[7,85],"o":"عاقبتهم: الرجفة، ويوم الظلّة."},{"id":"rass","t":"أصحاب الرس","d":"لم يُعيّن القرآن موضعهم ولا زمنهم، واختلف المفسرون فيهم على أقوال (ابن كثير).","r":[25,38],"o":"عاقبتهم: حقّ عليهم وعيد الله لتكذيبهم الرسل."},{"id":"firaun","t":"فرعون ومصر","d":"قوم فرعون هم قبط مصر (ابن كثير)، وجاءهم موسى عليه السلام؛ ولم يسمِّ القرآن الفرعون ولا حدّد عصره.","r":[28,4],"o":"عاقبتهم: الإغراق، وترك جنات وعيون وزروع ومقام كريم."},{"id":"saba","t":"سبأ","d":"قبيلة معروفة في أداني اليمن، ومسكنهم بلدة يقال لها مأرب (السعدي)، ومنهم بلقيس صاحبة سليمان (ابن كثير).","r":[34,15],"o":"عاقبتهم: سيل العَرِم وتمزيقهم كل ممزَّق."},{"id":"dhulqarnayn","t":"ذو القرنين","d":"ملك مكّن الله له في الأرض؛ ولم يُسمِّه القرآن ولم يُحدّد زمنه، وقد حذّر السعدي من الإسرائيليات فيه.","r":[18,84],"o":"أثره: سدّ يحجز يأجوج ومأجوج، «هذا رحمة من ربي»."},{"id":"ukhdud","t":"أصحاب الأخدود","d":"قوم كافرون فتنوا قوماً مؤمنين وحفروا الأخدود وأضرموا فيه النار (السعدي)؛ ولم يعيّن القرآن موضعهم.","r":[85,4],"o":"عاقبتهم: «قُتل أصحاب الأخدود»، ولهم عذاب الحريق."},{"id":"tubba","t":"قوم تُبّع","d":"تُبّع لقب ملوك اليمن قبل الإسلام (السعدي)، وقومه هم سبأ عند ابن كثير؛ ولم يُعيَّن أيّ تُبّع.","r":[44,37],"o":"عاقبتهم: أهلكهم الله لإجرامهم، فحقّ وعيد."},{"id":"rum","t":"الروم والفرس","d":"كانتا من أقوى دول الأرض وقت نزول الآيات (السعدي)، وقد وعد الله بغلبة الروم في بضع سنين.","r":[30,2],"o":"العبرة: «لله الأمر من قبل ومن بعد»."},{"id":"israel","t":"بنو إسرائيل","d":"فُضّلوا على عالمي زمانهم، واستُضعفوا عند فرعون ثم ورثوا أرضه ومُلّكوا.","r":[2,47],"o":"سنّتهم: إفسادان في الأرض ثم تسليط الأعداء."},{"id":"fil","t":"أصحاب الفيل","d":"جمع من الحبشة واليمن قصدوا هدم الكعبة (السعدي)، في العام الذي وُلد فيه النبي ﷺ على أشهر الأقوال (ابن كثير).","r":[105,1],"o":"عاقبتهم: طير أبابيل ترميهم بحجارة من سجّيل، فجُعلوا كعصف مأكول."}],"ch":[{"id":"sunan","t":"سنن الله في الحضارات: التمكين ثم الجحود ثم الهلاك","d":"تتكرر في قصص الأمم صورة واحدة: تمكين في الأرض وقوة وعمران، ثم جحود للنعمة وتكذيب للرسل، ثم أخذ بالذنوب بعد إقامة الحجة. ولهذا أمر الله بالسير في الأرض والنظر في عاقبة من قبلنا، فما قصّ علينا أخبارهم للتسلية بل للعبرة.","ay":[{"t":"السير في الأرض للعبرة","r":[12,109],"n":"دعوة إلى النظر في عاقبة الأمم السابقة بالقلب والعين، وهي بوابة هذا الركن كله."},{"t":"أشد منهم قوة وآثاراً","r":[30,9],"n":"الأمم الهالكة كانت أقوى من قريش وأكثر عمراناً، ولم يدفع عنها ذلك شيئاً حين كذّبت."},{"t":"ولقد مكّناهم فيما إن مكّناكم فيه","r":[46,26],"n":"مُنح الأولون السمع والأبصار والأفئدة، فما أغنت عنهم إذ جحدوا بآيات الله."},{"t":"أمرنا مترفيها ففسقوا فيها","r":[17,16],"n":"الترف إذا انفلت من الشكر والاستقامة صار باب الفسق ثم الهلاك بعد الأمر والإنذار."},{"t":"لا يهلك القرى حتى يبعث رسولاً","r":[28,59],"n":"لا يُهلك الله قرية إلا بعد إقامة الحجة وبعثة الرسول، وبعد أن يظلم أهلها."},{"t":"لا يهلك القرى بظلم وأهلها مصلحون","r":[11,117],"n":"الإهلاك عدل منه سبحانه، وسببه الظلم والفساد لا مجرد التمكين والعمران."},{"t":"في قصصهم عبرة لأولي الألباب","r":[12,111],"n":"القصص في القرآن تفصيل وهدى ورحمة لمن آمن، وأخبارها صدق لا اختلاق."}]},{"id":"nuh","t":"قوم نوح: أول طوفان في تاريخ البشرية","d":"أول رسول إلى أهل الأرض كما قال ابن كثير وكما جاء في حديث الشفاعة. دعا قومه ليلاً ونهاراً سنين طويلة، فما زادهم دعاؤه إلا فراراً، فصنع السفينة بأمر الله ونجا المؤمنون وأُغرق من سواهم.","ay":[{"t":"ألف سنة إلا خمسين عاماً","r":[29,14,15],"n":"مدة لبث نوح في قومه ثم أخذهم الطوفان وهم ظالمون، ونجاة أصحاب السفينة آيةً للعالمين."},{"t":"دعوة ليلاً ونهاراً","r":[71,5,9],"n":"دعوة بالسر والجهر لم تزد المعرضين إلا إصراراً واستكباراً، وجعلوا أصابعهم في آذانهم."},{"t":"ردّ الملأ: بشر مثلنا وأراذلنا","r":[11,25,27],"n":"اعترض كبراؤهم على بشرية الرسول وعلى أن الضعفاء اتبعوه، وهذه حجة المترفين في كل زمان."},{"t":"صناعة الفلك","r":[11,37,39],"n":"أمر الله نوحاً أن يصنع الفلك بأعينه ووحيه، وسخر منه قومه وهو يصنعها."},{"t":"الطوفان والنجاة","r":[11,40,44],"n":"فار التنور، وحُملت الأزواج والمؤمنون، وجرت السفينة في موج كالجبال، وقيل: يا أرض ابلعي ماءك."},{"t":"ابنه ليس من أهله","r":[11,45,47],"n":"النسب لا ينجي بغير الإيمان؛ فالنجاة معلّقة بالعمل الصالح لا بالقرابة.","h":"h_nuh"},{"t":"ولقد تركناها آية","r":[54,9,15],"n":"جعل الله السفينة آية باقية يُتذكّر بها، «فهل من مدّكر»."}]},{"id":"ad","t":"عاد: القوة والعمران وسبب السقوط","d":"أمة قوية البنية متطاولة العمران، جعلهم الله خلفاء من بعد قوم نوح وزادهم في الخلق بسطة. اغترّوا بقوتهم فقالوا: من أشد منا قوة؟ فأرسل الله إليهم هوداً فكذّبوه، فأُهلكوا بريح صرصر عاتية. وفي ذلك درس أن القوة بغير شكر لا تحمي صاحبها.","ay":[{"t":"جعلكم خلفاء من بعد قوم نوح","r":[7,65,69],"n":"دعوة هود إلى التوحيد وتذكيرهم بنعمة الاستخلاف وزيادة البسطة في الخلق."},{"t":"إرم ذات العماد","r":[89,6,8],"n":"ذكر الله عاداً بصفة قوة العمران، ولم يُخلق مثلها في البلاد في زمنها."},{"t":"من أشد منا قوة؟","r":[41,15,16],"n":"استكبروا في الأرض بغير الحق، فردّ الله عليهم: الله الذي خلقهم هو أشد منهم قوة."},{"t":"أتبنون بكل ريع آية تعبثون؟","r":[26,128,135],"n":"عاب عليهم هود البناء للاستعراض والعبث، واتخاذ المصانع كأنهم مخلدون، والبطش بالناس جبّارين."},{"t":"الأحقاف والعارض","r":[46,21,25],"n":"ظنوا السحاب الذي رأوه ممطراً فكان ريحاً فيها عذاب أليم تدمّر كل شيء بأمر ربها.","h":"h_ad2"},{"t":"ريح صرصر عاتية","r":[69,6,8],"n":"سبع ليال وثمانية أيام حسوماً، فصُرعوا كأنهم أعجاز نخل خاوية، فهل ترى لهم من باقية؟","h":"h_ad1"},{"t":"كأنهم أعجاز نخل منقعر","r":[54,18,20],"n":"العذاب أخذهم بقوتهم نفسها وهم الذين قالوا من أشد منا قوة، ثم جعلهم الله عبرة."}]},{"id":"thamud","t":"ثمود: النحت في الجبال والناقة الآية","d":"جاءوا بعد عاد، ومكّن الله لهم في الأرض يتخذون من سهولها قصوراً وينحتون الجبال بيوتاً. أرسل إليهم صالحاً بناقة الله آية فعقروها، فأخذتهم الصيحة والرجفة. وقد مرّ النبي ﷺ بديارهم في الحجر عام تبوك ونهى عن دخولها إلا باكين.","ay":[{"t":"هذه ناقة الله لكم آية","r":[7,73,79],"n":"ناقة خارقة لها شرب يوم ولهم شرب يوم معلوم، وحذّرهم صالح من المساس بها، وذكّرهم بالاستخلاف بعد عاد."},{"t":"ينحتون من الجبال بيوتاً آمنين","r":[15,80,84],"n":"أصحاب الحِجر كذّبوا المرسلين، وكانوا ينحتون من الجبال بيوتاً آمنين فما أغنى عنهم ما كانوا يكسبون.","h":"h_thamud1"},{"t":"أتتركون في ما هاهنا آمنين؟","r":[26,146,149],"n":"ذكّرهم صالح بجنات وعيون وزروع ونخل، وعاب عليهم نحت الجبال بيوتاً فرهين."},{"t":"تمتعوا في داركم ثلاثة أيام","r":[11,61,68],"n":"عقروا الناقة فأُمهلوا ثلاثة أيام، ثم جاءت الصيحة فأصبحوا في ديارهم جاثمين كأن لم يغنوا فيها."},{"t":"إذ انبعث أشقاها","r":[91,11,15],"n":"كذبوا بطغواهم فانبعث أشقاهم فعقرها، فدمدم عليهم ربهم بذنبهم فسوّاها.","h":"h_thamud2"},{"t":"ولقد يسّرنا القرآن للذكر","r":[54,23,31],"n":"جعل الله صيحة واحدة تحيلهم كهشيم المحتظر، وتكرر النداء: فهل من مدّكر؟"}]},{"id":"lut","t":"قوم لوط: الفاحشة التي لم يسبقهم بها أحد","d":"أُرسل لوط إلى أهل «سدوم» وما حولها من القرى، فنهاهم عن فاحشة ابتدعوها، فردّوا دعوته ثم همّوا بإخراجه وأهله لأنهم أناس يتطهرون. فنجّاه الله وأهله إلا امرأته، وأمطر على القوم حجارة وجعل عالي القرية سافلها.","ay":[{"t":"أتأتون الفاحشة ما سبقكم بها من أحد؟","r":[7,80,84],"n":"نهاهم لوط عن فاحشة لم تُعرف قبلهم، ووصفهم بالإسراف، وختم الله بقوله: فانظر كيف كان عاقبة المجرمين.","h":"h_lut2"},{"t":"أليس منكم رجل رشيد؟","r":[11,77,83],"n":"ضاق لوط بضيوفه ذرعاً، وقال: لو أن لي بكم قوة أو آوي إلى ركن شديد، فكشف الرسل أنهم رسل ربه.","h":"h_lut"},{"t":"لعمرك إنهم لفي سكرتهم يعمهون","r":[15,73,77],"n":"أخذتهم الصيحة مشرقين وجُعل عالي القرية سافلها، وفي ذلك لآيات للمتوسمين، وإنها لبسبيل مقيم."},{"t":"ما لهم يتطهرون","r":[27,54,58],"n":"قابلوا النصح بالسخرية من الطهارة، فأمطر الله عليهم مطراً فساء مطر المنذرين."},{"t":"نجيناهم بسحر","r":[54,33,39],"n":"أرسل عليهم حاصباً إلا آل لوط، نجاة نعمة من عند الله لمن شكر."}]},{"id":"madyan","t":"أصحاب مدين والأيكة: الغش في الكيل والميزان","d":"أرسل الله إلى مدين شعيباً يأمرهم بالتوحيد وإيفاء الكيل والميزان وأن لا يقعدوا بكل صراط يوعدون، فكذبوه. قال ابن كثير إن أصحاب الأيكة هم أهل مدين على الصحيح. وأُهلكوا بالرجفة وبعذاب يوم الظلة. وفي قصتهم ربط بين العدالة الاقتصادية والإيمان.","ay":[{"t":"أوفوا الكيل والميزان","r":[7,85,87],"n":"دعاهم شعيب إلى التوحيد وإيفاء الكيل والميزان وترك الإفساد بعد إصلاح الأرض."},{"t":"لا تقعدوا بكل صراط توعدون","r":[7,86,88],"n":"ذكّرهم بالنعمة إذ كانوا قليلاً فكثّرهم، وحذّرهم من صدّ الناس عن سبيل الله."},{"t":"قال الملأ: لنخرجنك يا شعيب","r":[7,88,93],"n":"هددوه بالإخراج، فقال إنه لا يعود في ملتهم بعد أن نجاه الله، ثم أخذتهم الرجفة فأصبحوا جاثمين."},{"t":"ويا قوم لا يجرمنكم شقاقي","r":[11,89,95],"n":"حذرهم أن يصيبهم مثل ما أصاب قوم نوح وهود وصالح ولوط، فلما جاء أمرنا نجينا شعيباً والذين آمنوا."},{"t":"أصحاب الأيكة المرسلين","r":[26,176,191],"n":"نسب القرآن هؤلاء إلى الأيكة ولم يقل أخوهم شعيب، فأخذهم عذاب يوم الظلة إنه كان عذاب يوم عظيم."},{"t":"وإنهما لبإمام مبين","r":[15,78,79],"n":"أصحاب الأيكة وقوم لوط أخذ الله منهم، وديارهم على طريق ظاهر يُعتبر به."}]},{"id":"rass","t":"أصحاب الرس: ما أُجمل وما اختُلف فيه","d":"ذكر القرآن أصحاب الرس في سياق الأمم المكذبة، ولم يبيّن موضعهم ولا نبيهم ولا زمنهم. فاختلف المفسرون: أهم قرية من قرى ثمود؟ أم أصحاب فلج باليمامة؟ أم أهل بئر بأذربيجان؟ والمقطوع به ما نصّ عليه القرآن من أنهم كذّبوا الرسل فحقّ وعيد الله.","ay":[{"t":"وعاداً وثمود وأصحاب الرس","r":[25,38,40],"n":"ذكرهم الله مع عاد وثمود وقروناً بين ذلك كثيراً، وضرب لكل الأمثال وتبّر كلاً تتبيراً."},{"t":"كذبت قبلهم قوم نوح وأصحاب الرس","r":[50,12,14],"n":"كل كذّب الرسل فحقّ وعيد: وفيه تسلية للنبي ﷺ وتخويف لمن كذّبه."}]},{"id":"firaun","t":"فرعون ومصر: الملك والعلوّ والأنهار تجري","d":"«إن فرعون علا في الأرض وجعل أهلها شيعاً يستضعف طائفة منهم». ملك عظيم في مصر بجنات وعيون وكنوز ومقام كريم وأنهار تجري من تحته، ادّعى الربوبية فأرسل الله إليه موسى وهارون. وبعد الآيات التسع أغرقه الله وجنوده وجعل بدنه آية، وأورث أرضه بني إسرائيل.","ay":[{"t":"إن فرعون علا في الأرض","r":[28,4,6],"n":"الاستعلاء وتقسيم الناس شيعاً واستضعاف طائفة، ثم إرادة الله أن يمنّ على المستضعفين ويجعلهم أئمة."},{"t":"أليس لي ملك مصر؟","r":[43,51,56],"n":"افتخر بملك مصر والأنهار تجري من تحته، فاستخف قومه فأطاعوه، وجعلهم الله سلفاً ومثلاً للآخرين."},{"t":"ما علمت لكم من إله غيري","r":[28,38],"n":"ادّعى الألوهية وأمر هامان بالبناء ليطّلع إلى إله موسى، فظهر استكباره بالباطل."},{"t":"ما كانوا يصنعون وما كانوا يعرشون","r":[7,137],"n":"ورّث الله القوم المستضعفين مشارق الأرض ومغاربها، ودمّر ما كان يصنع فرعون وقومه وما يعرشون."},{"t":"فأخرجناهم من جنات وعيون","r":[26,57,59],"n":"أخرجهم الله من جنات وعيون وكنوز ومقام كريم وأورثها بني إسرائيل.","h":"h_fir1"},{"t":"كم تركوا من جنات وعيون","r":[44,25,29],"n":"تركوا ما جمعوا لقوم آخرين، وما بكت عليهم السماء والأرض ولا كانوا منظرين."},{"t":"فاليوم ننجيك ببدنك","r":[10,90,92],"n":"لما أدركه الغرق آمن في لحظة اضطرار فلم يُقبل منه، وبقي بدنه آية لمن خلفه."},{"t":"امرأة فرعون","r":[66,11],"n":"آسية آمنت في بيت الطاغية وسألت الله بيتاً في الجنة، فجعلها الله مثلاً للذين آمنوا.","h":"h_fir2"}]},{"id":"saba","t":"سبأ: الجنتان والسد وسيل العرم","d":"«لقد كان لسبأ في مسكنهم آية: جنتان عن يمين وشمال»، بلدة طيبة ورب غفور. بنوا سداً يجمع السيول ويسقي البساتين، فلما أعرضوا أرسل الله عليهم سيل العرم وبدّل جنتيهم بأكل خمط وأثل وشيء من سدر قليل، ومزّقهم كل ممزّق. ومنهم بلقيس التي وصفها الهدهد بأنها «أوتيت من كل شيء ولها عرش عظيم».","ay":[{"t":"لقد كان لسبأ في مسكنهم آية","r":[34,15,16],"n":"جنتان عن يمين وشمال، وأُمروا بالأكل من رزق ربهم والشكر، فأعرضوا فأرسل عليهم سيل العرم.","h":"h_saba"},{"t":"وبدلناهم بجنتيهم جنتين","r":[34,16,17],"n":"صارت ثمارهم أكلاً خمطاً وأثلاً وشيئاً من سدر قليل، ذلك جزاؤهم بما كفروا."},{"t":"ربنا باعد بين أسفارنا","r":[34,18,19],"n":"كانت قرى ظاهرة متصلة تيسّر السير، فبطروا وقالوا باعد، وظلموا أنفسهم، فجعلهم أحاديث ومزقهم كل ممزق."},{"t":"امرأة تملكهم وأوتيت من كل شيء","r":[27,22,26],"n":"خبر الهدهد عن مملكة سبأ: ملكة، وسلطان، وعرش عظيم، وسجودهم للشمس من دون الله."},{"t":"ما كنت قاطعة أمراً حتى تشهدون","r":[27,29,35],"n":"ملكة تستشير ملأها ولا تقطع أمراً دونهم، وتقدّر عاقبة الحرب: إن الملوك إذا دخلوا قرية أفسدوها."},{"t":"أسلمت مع سليمان لله رب العالمين","r":[27,44],"n":"وصلت الملكة إلى الإيمان بعد رؤية الصرح: «رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين»."}]},{"id":"dhulqarnayn","t":"ذو القرنين: التمكين والعدل وبناء السدّ","d":"سأل المشركون عنه امتحاناً للنبي ﷺ، فأجاب القرآن بما فيه العبرة: ملك مكّن الله له في الأرض وآتاه من كل شيء سبباً، فسار مغرباً ومشرقاً، وعامل كل قوم بما يليق بهم. ثم أقام بين السدّين ردماً بقوة الحديد والقطر حاجزاً عن يأجوج ومأجوج، ونسب النعمة إلى ربه: «هذا رحمة من ربي».","ay":[{"t":"إنا مكنا له في الأرض وآتيناه من كل شيء سبباً","r":[18,83,85],"n":"التمكين الإلهي وأسباب القوة؛ ولم يبيّن القرآن أسماءها ولا تفاصيلها، فلا يُبنى عليها بالإسرائيليات."},{"t":"مغرب الشمس وسياسة العدل","r":[18,86,88],"n":"خُيّر بين التعذيب والإحسان فعدل: من ظلم عذّبه، ومن آمن وعمل صالحاً فله الحسنى وقول يسير."},{"t":"مطلع الشمس","r":[18,89,91],"n":"أتبع سبباً حتى بلغ مطلع الشمس، ووجدها تطلع على قوم لم يجعل الله لهم من دونها ستراً."},{"t":"بين السدين وقوم لا يكادون يفقهون قولاً","r":[18,92,94],"n":"شكا القوم إفساد يأجوج ومأجوج وعرضوا خرجاً ليبني سدّاً بينهم وبينهم."},{"t":"أعينوني بقوة أجعل بينكم وبينهم ردماً","r":[18,95,97],"n":"رفض الأجر وطلب العون بقوة الرجال: زُبَر الحديد حتى ساوى بين الصدفين، ثم أفرغ عليه قطراً فما اسطاعوا أن يظهروه وما استطاعوا له نقباً.","h":"h_yajuj"},{"t":"هذا رحمة من ربي","r":[18,98],"n":"نسب النجاح إلى فضل ربه، وذكّر بأن الردم سيُدكّ عند مجيء وعد الله."},{"t":"حتى إذا فتحت يأجوج ومأجوج","r":[21,96,97],"n":"خروجهم من أشراط الساعة وهم من كل حدب ينسلون، واقتراب الوعد الحق."}]},{"id":"ukhdud","t":"أصحاب الأخدود: الثبات على الإيمان أمام الجبروت","d":"«قُتل أصحاب الأخدود النار ذات الوقود، إذ هم عليها قعود وهم على ما يفعلون بالمؤمنين شهود، وما نقموا منهم إلا أن يؤمنوا بالله العزيز الحميد». حضارة مادية ملكت القوة وحاربت الإيمان بالتعذيب، فكانت عاقبتها اللعنة، وثبت المؤمنون فكان لهم الفوز الكبير. ولم يعيّن القرآن موضعهم.","ay":[{"t":"قتل أصحاب الأخدود","r":[85,4,9],"n":"دعاء عليهم بالهلاك، ووصف لجبروتهم: قعود على النار شهود على تعذيب المؤمنين، ولا ذنب لهم إلا الإيمان.","h":"h_ukhdud"},{"t":"إن الذين فتنوا المؤمنين","r":[85,10,11],"n":"وعيد التائبين وغير التائبين: لهم عذاب جهنم وعذاب الحريق، وللذين آمنوا جنات تجري من تحتها الأنهار."},{"t":"هل أتاك حديث الجنود","r":[85,17,20],"n":"ذكّر الله بفرعون وثمود: الجنود الطغاة سنّتهم واحدة، والله من ورائهم محيط."}]},{"id":"tubba","t":"قوم تُبّع: ملوك اليمن قبل الإسلام","d":"ذكر القرآن قوم تُبّع في سورتي الدخان وق مثلاً لمن أنكروا البعث. و«تُبّع» لقب لمن ملك اليمن في الزمن السابق، قال السعدي، ولم يخبرنا الله من هو الرسول ولا أيّ تُبّع. وفي الحديث الصحيح قول النبي ﷺ: «ما أدري أتُبّع لعين هو أم لا»، وفيه الورع في الحكم على من لم يرد فيه نص.","ay":[{"t":"أهم خير أم قوم تُبّع؟","r":[44,37],"n":"سؤال تقريع لقريش: ليسوا خيراً من أمم أهلكها الله لإجرامها، فليحذروا مثل مصيرها.","h":"h_tubba"},{"t":"وقوم تُبّع كل كذّب الرسل","r":[50,14],"n":"كل كذّب الرسل فحقّ وعيد: قاعدة عامة تضمّ الأمم المذكورة جميعاً."}]},{"id":"rum","t":"الروم والفرس: دول تتداول","d":"في سورة الروم خبر عن دولتين عظيمتين كانتا تتصارعان وقت نزول الآيات، وإخبار قبل وقوعه بأن الروم ستغلب في بضع سنين. والدرس أن الغلبة والنصر ليستا بمجرد الأسباب، فـ«لله الأمر من قبل ومن بعد». وفي الصحيح أن النبي ﷺ بشّر بزوال ملك كسرى وقيصر وإنفاق كنوزهما في سبيل الله.","ay":[{"t":"غلبت الروم في أدنى الأرض","r":[30,1,4],"n":"خبر بغلبة الروم بعد غلبهم في بضع سنين، وإقرار أن الأمر لله من قبل ومن بعد.","h":"h_rum2"},{"t":"وعد الله لا يخلف الله وعده","r":[30,5,7],"n":"يفرح المؤمنون بنصر الله، ووعده حق، ولكن أكثر الناس لا يعلمون ظاهراً من الحياة الدنيا وهم عن الآخرة غافلون.","h":"h_rum1"},{"t":"ثم كان عاقبة الذين أساؤوا السوأى","r":[30,9,10],"n":"ربط السياق بين غلبة الدول وسنة الله في الأمم السابقة التي كانت أقوى وأكثر آثاراً."}]},{"id":"israel","t":"بنو إسرائيل: التفضيل والإفسادان","d":"ذكر القرآن بني إسرائيل أكثر من غيرهم: فضّلهم على العالمين، وأنجاهم من فرعون، وآتاهم الكتاب والحكم والنبوة، وجعلهم ملوكاً، ثم عاب عليهم نقض العهد وقتل الأنبياء وتحريف الكلم. وأخبر أنهم يفسدون في الأرض إفسادين، يسلّط الله عليهم في كل مرة من يسوؤهم، لعلهم يرجعون.","ay":[{"t":"فضلتكم على العالمين","r":[2,47,50],"n":"ذكّرهم بالنعمة، وبالنجاة من آل فرعون، وفرق البحر وغرقهم وهم ينظرون.","h":"h_isr1"},{"t":"لتفسدنّ في الأرض إفسادين","r":[17,4,8],"n":"قضى الله في الكتاب: إفسادان وعلو كبير، وتسليط عباد أولي بأس، ثم رد الكرّة، ثم وعد الآخرة، «وإن عدتم عدنا»."},{"t":"ادخلوا الأرض المقدسة","r":[5,20,26],"n":"أمرهم موسى بدخول الأرض المقدسة فنكصوا خوفاً من الجبّارين، فحُرّمت عليهم أربعين سنة يتيهون في الأرض."},{"t":"الملأ من بني إسرائيل بعد موسى","r":[2,246,251],"n":"طلبوا ملكاً يقاتلون معه، فبعث الله طالوت، وانتصروا بإذن الله وقتل داود جالوت وآتاه الله الملك والحكمة.","h":"h_isr2"},{"t":"لُعن الذين كفروا من بني إسرائيل","r":[5,78,79],"n":"سبب اللعن: العصيان والاعتداء، وتركهم التناهي عن المنكر الذي فعلوه."}]},{"id":"fil","t":"أصحاب الفيل: حفظ البيت الحرام","d":"جاء جمع من الحبشة واليمن بالفيلة لهدم الكعبة، ولم يكن بالعرب مدافعة، فأرسل الله عليهم طيراً أبابيل ترميهم بحجارة من سجيل فجعلهم كعصف مأكول. وكانت إرهاصاً بمبعث النبي ﷺ، وامتن الله بها على قريش.","ay":[{"t":"ألم تر كيف فعل ربك بأصحاب الفيل","r":[105,1,5],"n":"كيدهم في تضليل، وطير أبابيل بحجارة من سجيل، فكانوا كعصف مأكول.","h":"h_fil"},{"t":"لإيلاف قريش","r":[106,1,4],"n":"نعمة الأمن والرزق في الرحلتين مقابل عبادة رب هذا البيت."}]}],"h":[{"id":"h_nuh","t":"نوح أول الرسل إلى أهل الأرض","x":"يَا نُوحُ أَنْتَ أَوَّلُ الرُّسُلِ إِلَى أَهْلِ الأَرْضِ، وَسَمَّاكَ اللَّهُ عَبْدًا شَكُورًا","src":[["bukhari","3340"],["bukhari","4712"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من حديث الشفاعة: الناس يأتون نوحاً يوم القيامة فيصفونه بأنه أول الرسل إلى أهل الأرض وبأن الله سماه عبداً شكوراً.","en":"\"People will come to Nuh and say: Nuh, you are the first of the messengers to the people of the earth, and God named you a grateful servant.\"","ch":"nuh"},{"id":"h_ad1","t":"نصرت بالصبا وأهلكت عاد بالدبور","x":"نُصِرْتُ بِالصَّبَا، وَأُهْلِكَتْ عَادٌ بِالدَّبُورِ","src":[["bukhari","3205"],["bukhari","1035"],["muslim","900"]],"gr":"صحيح: متفق عليه","dg":"","f":"الريح جند من جنود الله: تكون نصراً لقوم وهلاكاً لآخرين بأمره، فعاد أُهلكت بريح الدبور الباردة العاتية.","en":"\"I was given victory with the east wind (as-saba), and 'Ad were destroyed with the west wind (ad-dabur).\"","ch":"ad"},{"id":"h_ad2","t":"خشية النبي ﷺ من الغيم أن يكون عذاباً","x":"مَا يُؤْمِنِّي أَنْ يَكُونَ فِيهِ عَذَابٌ عُذِّبَ قَوْمٌ بِالرِّيحِ","src":[["bukhari","4829"]],"gr":"صحيح: رواه البخاري","dg":"","f":"كان النبي ﷺ إذا رأى غيماً أو ريحاً عُرف في وجهه خوفاً أن يكون عذاباً، تذكّراً لما أصاب قوم عاد حين ظنوا العارض ممطراً.","en":"\"What assures me that it does not carry punishment? A people were punished by the wind.\"","ch":"ad"},{"id":"h_thamud1","t":"لا تدخلوا مساكن الذين ظلموا إلا باكين","x":"لاَ تَدْخُلُوا مَسَاكِنَ الَّذِينَ ظَلَمُوا إِلاَّ أَنْ تَكُونُوا بَاكِينَ، أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ","src":[["bukhari","3380"],["bukhari","4419"],["muslim","2980"]],"gr":"صحيح: متفق عليه","dg":"","f":"ديار المعذَّبين موضع عبرة لا نزهة: من مرّ بها يمرّ خاشعاً باكياً خوفاً أن يصيبه ما أصابهم.","en":"\"Do not enter the dwellings of those who wronged themselves unless weeping, lest what befell them befall you.\"","ch":"thamud"},{"id":"h_thamud2","t":"عاقر الناقة: رجل عزيز عارم منيع في رهطه","x":"انْبَعَثَ لَهَا رَجُلٌ عَزِيزٌ عَارِمٌ، مَنِيعٌ فِي رَهْطِهِ، مِثْلُ أَبِي زَمْعَةَ","src":[["bukhari","4942"]],"gr":"صحيح: رواه البخاري","dg":"","f":"وصف النبي ﷺ عاقر الناقة بأنه عزيز في قومه منيع، فالفساد يقوده المتنفذ ويتبعه جمع.","en":"\"A man of power, vicious and well protected among his clan, like Abu Zam'a, rose up for it.\"","ch":"thamud"},{"id":"h_lut","t":"يرحم الله لوطاً، لقد كان يأوي إلى ركن شديد","x":"يَرْحَمُ اللَّهُ لُوطًا، لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ","src":[["bukhari","3387"],["bukhari","3372"]],"gr":"صحيح: رواه البخاري","dg":"","f":"الركن الشديد هو الله سبحانه؛ والمعنى أن لوطاً نسي في ضيقه أنه يأوي إلى أقوى سند.","en":"\"May God have mercy on Lut: he used to take refuge in a strong support.\"","ch":"lut"},{"id":"h_lut2","t":"أخوف ما أخاف على أمتي عمل قوم لوط","x":"إِنَّ أَخْوَفَ مَا أَخَافُ عَلَى أُمَّتِي عَمَلُ قَوْمِ لُوطٍ","src":[["tirmidhi","1457"]],"gr":"","dg":"الألباني: حسن؛ أحمد شاكر: حسن؛ بشار عواد معروف: حسن؛ زبير علي زئي: ضعيف","f":"تحذير نبوي من الوقوع فيما أُهلك به قوم لوط، وقد حكم عليه أهل الحديث بالحسن على خلاف بينهم في درجته كما يظهر في بيان درجته.","en":"\"The thing I fear most for my nation is the act of the people of Lut.\"","ch":"lut"},{"id":"h_fir1","t":"يوم عاشوراء: غرق فرعون ونجاة موسى","x":"هَذَا يَوْمٌ عَظِيمٌ أَنْجَى اللَّهُ فِيهِ مُوسَى وَقَوْمَهُ وَغَرَّقَ فِرْعَوْنَ وَقَوْمَهُ فَصَامَهُ مُوسَى شُكْرًا","src":[["muslim","1130"],["bukhari","2004"]],"gr":"صحيح: متفق عليه","dg":"","f":"شكر النجاة من الطغيان عبادة، ولذلك صام موسى هذا اليوم ثم صامه النبي ﷺ وأمر بصيامه.","en":"\"This is a great day on which God saved Musa and his people and drowned Pharaoh and his people, so Musa fasted it in gratitude.\"","ch":"firaun"},{"id":"h_fir2","t":"آسية امرأة فرعون من كمل النساء","x":"كَمَلَ مِنَ الرِّجَالِ كَثِيرٌ وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ غَيْرُ مَرْيَمَ بِنْتِ عِمْرَانَ وَآسِيَةَ امْرَأَةِ فِرْعَوْنَ","src":[["muslim","2431"]],"gr":"صحيح: رواه مسلم","dg":"","f":"الإيمان لا يمنعه جبروت الحاكم ولا قرب الزوج، وقد جعل الله آسية مثلاً للذين آمنوا.","en":"\"Many men attained perfection, but among women none attained it except Maryam daughter of 'Imran and Asiya wife of Pharaoh.\"","ch":"firaun"},{"id":"h_saba","t":"سبأ: رجل ولد عشرة من العرب","x":"لَيْسَ بِأَرْضٍ وَلاَ امْرَأَةٍ وَلَكِنَّهُ رَجُلٌ وَلَدَ عَشَرَةً مِنَ الْعَرَبِ فَتَيَامَنَ مِنْهُمْ سِتَّةٌ وَتَشَاءَمَ مِنْهُمْ أَرْبَعَةٌ فَأَمَّا الَّذِينَ تَشَاءَمُوا فَلَخْمٌ وَجُذَامٌ وَغَسَّانُ وَعَامِلَةٌ وَأَمَّا الَّذِينَ تَيَامَنُوا فَالأَزْدُ وَالأَشْعَرِيُّونَ وَحِمْيَرُ وَمَذْحِجٌ وَأَنْمَارُ وَكِنْدَةُ","src":[["tirmidhi","3222"]],"gr":"","dg":"الألباني: حسن صحيح؛ أحمد شاكر: حسن صحيح؛ بشار عواد معروف: حسن؛ زبير علي زئي: إسناده حسن","f":"بيّن النبي ﷺ أن سبأ اسم رجل تفرع منه عشر قبائل عربية، فتكون الآيات في أمة معروفة النسب لا في خرافة.","en":"\"It is neither a land nor a woman, but a man who fathered ten of the Arabs. Six of them went toward Yemen and four toward the Sham. As for those who went to the Sham: Lakhm, Judham, Ghassan and 'Amila. As for those who went to Yemen: al-Azd, al-Ash'ariyyun, Himyar, Madhhij, Anmar and Kinda.\"","ch":"saba"},{"id":"h_yajuj","t":"فُتح من ردم يأجوج ومأجوج مثل هذا","x":"فَتَحَ اللَّهُ مِنْ رَدْمِ يَأْجُوجَ وَمَأْجُوجَ مِثْلَ هَذَا","src":[["bukhari","3347"],["bukhari","3346"],["muslim","2880"]],"gr":"صحيح: متفق عليه","dg":"","f":"أخبر النبي ﷺ أن الردم قد فُتح منه ما يشبه حلقة عقدها بيده، وهو من أشراط الساعة التي حذّر منها.","en":"\"God has opened of the rampart of Yajuj and Majuj the like of this,\" and he made a circle with his hand (ninety).","ch":"dhulqarnayn"},{"id":"h_ukhdud","t":"حديث الغلام: اصبري فإنك على الحق (مقتطف)","x":"فَأَمَرَ بِالأُخْدُودِ فِي أَفْوَاهِ السِّكَكِ فَخُدَّتْ وَأَضْرَمَ النِّيرَانَ وَقَالَ مَنْ لَمْ يَرْجِعْ عَنْ دِينِهِ فَأَحْمُوهُ فِيهَا . أَوْ قِيلَ لَهُ اقْتَحِمْ . فَفَعَلُوا حَتَّى جَاءَتِ امْرَأَةٌ وَمَعَهَا صَبِيٌّ لَهَا فَتَقَاعَسَتْ أَنْ تَقَعَ فِيهَا فَقَالَ لَهَا الْغُلاَمُ يَا أُمَّهِ اصْبِرِي فَإِنَّكِ عَلَى الْحَقِّ","src":[["muslim","3005"]],"gr":"صحيح: رواه مسلم","dg":"","f":"مقتطف من حديث الغلام الطويل عند مسلم: ثبات المؤمنين على الحق أمام النار، وأن التثبيت يأتي من الله، وأن الصبر على الأذى طريق الفوز.","en":"\"He ordered trenches dug at the mouths of the roads, they were dug and fires kindled; and he said: whoever does not turn back from his religion, throw him in it, or it was said to him: plunge in. They did so, until a woman came with her child who hesitated to fall in; the boy said: Mother, be patient, for you are on the truth.\"","ch":"ukhdud"},{"id":"h_tubba","t":"ما أدري أتُبّع لعين هو أم لا","x":"مَا أَدْرِي أَتُبَّعٌ لَعِينٌ هُوَ أَمْ لاَ","src":[["abudawud","4674"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"توقف النبي ﷺ فيما لم يُوحَ إليه فيه، وفي هذا درس في الورع وترك الجزم بلا دليل في أحوال الأمم.","en":"\"I do not know whether Tubba' was accursed or not.\"","ch":"tubba"},{"id":"h_rum1","t":"إذا هلك كسرى فلا كسرى بعده","x":"إِذَا هَلَكَ كِسْرَى فَلاَ كِسْرَى بَعْدَهُ، وَإِذَا هَلَكَ قَيْصَرُ فَلاَ قَيْصَرَ بَعْدَهُ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَتُنْفِقُنَّ كُنُوزَهُمَا فِي سَبِيلِ اللَّهِ","src":[["bukhari","3618"],["bukhari","3120"],["muslim","2918"]],"gr":"صحيح: متفق عليه","dg":"","f":"خبر نبوي بزوال دولتين عظيمتين وانتقال كنوزهما إلى المسلمين، وقد وقع كما أخبر.","en":"\"When Kisra perishes there will be no Kisra after him, and when Qaysar perishes there will be no Qaysar after him; by the One in whose hand is my soul, their treasures will be spent in the way of God.\"","ch":"rum"},{"id":"h_rum2","t":"سبب نزول: فرح المؤمنين بظهور الروم","x":"لَمَّا كَانَ يَوْمُ بَدْرٍ ظَهَرَتِ الرُّومُ عَلَى فَارِسَ فَأَعْجَبَ ذَلِكَ الْمُؤْمِنِينَ فَنَزَلَتْ : ( الم *غَلَبَتِ الرُّومُ ) إِلَى قَوْلِهِ : (يفْرَحُ الْمُؤْمِنُونَ بِنَصْرِ اللَّهِ ) قَالَ فَفَرِحَ الْمُؤْمِنُونَ بِظُهُورِ الرُّومِ عَلَى فَارِسَ","src":[["tirmidhi","3192"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح لغيره؛ بشار عواد معروف: حسن؛ زبير علي زئي: حسن","f":"يروي سبب نزول آيات سورة الروم وفرح المؤمنين بظهور أهل الكتاب على المجوس، وقد اختلف في درجته كما يظهر في الأحكام عليه.","en":"\"On the day of Badr the Romans prevailed over the Persians, which pleased the believers; so it was revealed: Alif Lam Mim. The Romans have been defeated ... until: the believers rejoice. The believers rejoiced at the Romans' prevailing over the Persians.\"","ch":"rum"},{"id":"h_isr1","t":"كانت بنو إسرائيل تسوسهم الأنبياء","x":"كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الأَنْبِيَاءُ، كُلَّمَا هَلَكَ نَبِيٌّ خَلَفَهُ نَبِيٌّ، وَإِنَّهُ لاَ نَبِيَّ بَعْدِي","src":[["bukhari","3455"]],"gr":"صحيح: رواه البخاري","dg":"","f":"كان الأنبياء يسوسون بني إسرائيل بالشرع والسياسة معاً، ثم أُمر المسلمون بالوفاء للبيعة والحفاظ على الأمانة.","en":"\"The Children of Israel were governed by prophets: whenever a prophet died another succeeded him, but there will be no prophet after me.\"","ch":"israel"},{"id":"h_isr2","t":"لتتبعن سنن من كان قبلكم","x":"لَتَتْبَعُنَّ سَنَنَ مَنْ كَانَ قَبْلَكُمْ شِبْرًا شِبْرًا وَذِرَاعًا بِذِرَاعٍ، حَتَّى لَوْ دَخَلُوا جُحْرَ ضَبٍّ تَبِعْتُمُوهُمْ","src":[["bukhari","7320"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تحذير من متابعة الأمم السابقة في أخطائها؛ فسنن الله تجري على الأمم جميعاً، ولا تحمي الأمة انتسابها وحده.","en":"\"You will follow the ways of those before you, span by span and cubit by cubit, until if they entered a lizard's hole you would follow them.\"","ch":"israel"},{"id":"h_fil","t":"حبسها حابس الفيل","x":"مَا خَلأَتِ الْقَصْوَاءُ، وَمَا ذَاكَ لَهَا بِخُلُقٍ، وَلَكِنْ حَبَسَهَا حَابِسُ الْفِيلِ","src":[["bukhari","2731"],["bukhari","2732"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ذكر النبي ﷺ أن الله هو الذي حبس ناقته عن دخول مكة يوم الحديبية كما حبس الفيل عنها قديماً.","en":"\"Al-Qaswa did not balk, that is not her nature, but the One who held back the elephant held her back.\"","ch":"fil"},{"id":"h_gen1","t":"إن الله ليملي للظالم","x":"إِنَّ اللَّهَ لَيُمْلِي لِلظَّالِمِ حَتَّى إِذَا أَخَذَهُ لَمْ يُفْلِتْهُ","src":[["bukhari","4686"]],"gr":"صحيح: رواه البخاري","dg":"","f":"الإمهال ليس إهمالاً: يؤخّر الله الظالم ثم يأخذه أخذ عزيز مقتدر، وقد قرأ النبي ﷺ آية هود في ذلك.","en":"\"God grants the wrongdoer respite until, when He seizes him, He lets him not escape.\"","ch":"sunan"},{"id":"h_gen2","t":"أنهلك وفينا الصالحون؟ نعم إذا كثر الخبث","x":"أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ، إِذَا كَثُرَ الْخُبْثُ","src":[["bukhari","3346"],["bukhari","3598"],["muslim","2880"]],"gr":"صحيح: متفق عليه","dg":"","f":"وجود الصالحين لا يمنع الهلاك إذا كثر الفساد ولم يُنكر؛ فتغيير المنكر وإصلاح المجتمع مسؤولية جماعية.","en":"\"Shall we be destroyed while the righteous are among us?\" He said: \"Yes, when evil abounds.\"","ch":"sunan"}],"q":[{"ch":"sunan","w":"السعدي","bk":"saadi","s":30,"ay":9,"x":"فإنَّهم حين ينظُرون في آثار أولئك؛ لم يجِدوا إلاَّ أمماً بائدةً، وخلقاً مهلَكين، ومنازل بعدهم موحشة. وذمٌّ من الخلق عليهم متتابعٌ، وهذا جزاءٌ معجَّل نموذج للجزاء الأخروي ومبتدأ له","n":"حين ينظر الإنسان في آثار الأمم الهالكة يرى قوتهم لم تغنِ عنهم، وهذا الجزاء المعجّل بداية للجزاء الأخروي.","en":"\"For when they look at the traces of those, they find nothing but perished nations, destroyed creatures, and desolate dwellings after them, and continuous censure from creation upon them; and this is a hastened recompense, a model of the Hereafter's recompense and its beginning.\""},{"ch":"sunan","w":"السعدي","bk":"saadi","s":11,"ay":117,"x":"أي: وما كان الله ليهلك القرى بظُلم منه لهم والحالُ أنَّهم {مصلحون}؛ أي: مقيمون على الصلاح مستمرون عليه؛ فما كان الله ليهلكهم إلا إذا ظلموا، وقامت عليهم حجَّة الله","n":"الإهلاك عدل لا ظلم، يقع حين يقيمون على الظلم بعد قيام الحجة.","en":"\"That is: God would never destroy the towns unjustly while they were reformers, persisting in righteousness; God does not destroy them except when they wrong and God's proof has been established against them.\""},{"ch":"nuh","w":"السعدي","bk":"saadi","s":71,"ay":1,"x":"لم يذكر الله في هذه السورة إلاَّ قصَّة نوح وحدَها؛ لطول لَبْثِهِ في قومه وتكرار دعوته إلى التوحيد ونهيه عن الشرك","n":"سورة كاملة لقصة نوح وحده لطول دعوته.","en":"\"God mentioned in this surah only the story of Nuh alone, because of the length of his stay among his people, the repetition of his call to monotheism, and his forbidding of shirk.\""},{"ch":"nuh","w":"ابن كثير","bk":"ibnkathir","s":29,"ay":14,"x":"أَنَّهُ مَكَثَ فِي قَوْمِهِ هَذِهِ الْمُدَّةَ يَدْعُوهُمْ إِلَى اللَّهِ لَيْلًا وَنَهَارًا، وَسِرًّا، وجهارًا، وَمَعَ هَذَا مَا زَادَهُمْ ذَلِكَ إِلَّا فِرَارًا عَنِ الْحَقِّ، وَإِعْرَاضًا عَنْهُ وَتَكْذِيبًا لَهُ، وَمَا آمَنُ مَعَهُ مِنْهُمْ إِلَّا قَلِيلٌ","n":"دعا سراً وجهاراً وليلاً ونهاراً، ولم يؤمن معه إلا قليل.","en":"\"That he remained among his people for this period calling them to God night and day, secretly and openly, and with all this it only increased them in fleeing from the truth, turning away from it and denying it, and only a few believed with him from among them.\""},{"ch":"nuh","w":"ابن كثير","bk":"ibnkathir","s":25,"ay":38,"x":"وَلِهَذَا أَغْرَقَهُمُ الله جَمِيعًا، وَلَمْ يَبق مِنْهُمْ أَحَدٌ، وَلَمْ يَبْقَ عَلَى وَجْهِ الْأَرْضِ مِنْ بَنِي آدَمَ سِوَى أَصْحَابِ السَّفِينَةِ فَقَطْ","n":"لم ينجُ من الطوفان إلا أصحاب السفينة، فالبشر كلهم من ذرية من آمن.","en":"\"For this God drowned them all, and none of them remained, and none remained on the face of the earth of the children of Adam except the people of the Ark alone.\""},{"ch":"ad","w":"السعدي","bk":"saadi","s":89,"ay":6,"x":"بهذه الأمم الطاغية، عاد وهي {إرم}: القبيلة المعروفة في اليمن، {ذات العِماد}؛ أي: القوَّة الشديدة والعتوِّ والتجبُّر، {التي لم يُخۡلَقۡ مثلُها في البلاد} ؛ أي: في جميع البلدان في القوَّة والشدَّة؛ كما قال لهم نبيُّهم هودٌ عليه السلام:{واذكُروا إذۡ جَعَلَكُم خُلَفاء من بعدِ قوم نوح وزادَكُم في الخَلۡقِ بَسۡطَةً فاذكُروا آلاء الله لعلَّكُم تفلِحونَ}. {وثمودَ الذين جابوا الصَّخۡر بالواد}؛ أي: وادي القرى؛ نحتوا بقوَّتهم الصخور فاتَّخذوها مساكن، {وفرعونَ ذي الأوتادِ}؛ أي: ذي الجنود الذي ثبَّتوا ملكه كما تثبت الأوتاد [و] ما يراد إمساكه بها، {الذين طَغَوۡا في البلاد}: هذا الوصف عائدٌ إلى عادٍ وثمودَ وفرعونَ ومن تَبِعَهم؛ فإنَّهم طَغَوْا في بلاد الله، وآذوا عباد الله في دينهم ودنياهم. ولهذا قال:{فأكثروا فيها الفسادَ}: وهو العمل بالكفر وشعبه من جميع أجناس المعاصي، وسعوا في محاربة الرُّسُل وصدِّ الناس عن سبيل الله، فلما بلغوا من العتوِّ ما هو موجبٌ لهلاكهم؛ أرسل الله عليهم من عذابه ذَنُوباً وسوطَ عذاب، {إنَّ ربَّك لبالمرصادِ}: لمن يعصيه ؛ يمهِلُه قليلاً ثم يأخُذُه أخذَ عزيزٍ مقتدرٍ","n":"يجمع عاداً وثمود وفرعون في سنة واحدة: طغيان وإفساد ثم أخذ.","en":"\"With these tyrannical nations: 'Ad ... Thamud ... and Pharaoh, owner of the stakes. They are the ones who transgressed in the lands, and multiplied corruption therein; so God sent upon them a portion of His punishment and a lash of torment. Indeed your Lord is ever watchful: He gives respite to whoever disobeys Him a little, then seizes him with the seizing of the Almighty, the Able.\""},{"ch":"ad","w":"ابن كثير","bk":"ibnkathir","s":7,"ay":65,"x":"وَقَدْ كَانَتْ مَسَاكِنُهُمْ باليمن بالأحقاف، وهي جبال الرمل. قَالَ مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَعِيدٍ الْخُزَاعِيِّ، عَنْ أَبِي الطُّفَيْلِ عَامِرِ بْنِ وَاثِلَةَ، سَمِعْتُ عَلِيَّ بْنَ أَبِي طَالِبٍ [رَضِيَ اللَّهُ عَنْهُ] يَقُولُ لِرَجُلٍ مِنْ حَضْرَمَوْتَ: هَلْ رَأَيْتَ كَثِيبًا أَحْمَرَ تُخَالِطُهُ مَدَرَة حَمْرَاءُ ذَا أرَاكٍ وسدْر كَثِيرٍ بِنَاحِيَةِ كَذَا وَكَذَا مِنْ أَرْضِ حَضْرَمَوْتَ، هَلْ رَأَيْتَهُ؟ قَالَ: نَعَمْ يَا أَمِيرَ الْمُؤْمِنِينَ. وَاللَّهِ إِنَّكَ لَتَنْعَتُهُ نعتَ رَجُلٍ قَدْ رَآهُ. قَالَ: لَا وَلَكِنِّي قَدْ حدِّثتُ عَنْهُ. فَقَالَ الْحَضْرَمِيُّ: وَمَا شَأْنُهُ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: فِيهِ قبرُ هُودٍ، عَلَيْهِ السَّلَامُ. رَوَاهُ ابْنُ جَرِيرٍ وَهَذَا فِيهِ فَائِدَةٌ أَنَّ مَسَاكِنَهُمْ كَانَتْ بِالْيَمَنِ، وَأَنَّ هُودًا، عَلَيْهِ السَّلَامُ، دُفِنَ هُنَاكَ","n":"ذكر مساكن عاد في الأحقاف باليمن وموضع قبر هود بحسب ما رواه.","en":"\"Their dwellings were in Yemen in al-Ahqaf, which are the sand mountains. Muhammad ibn Ishaq narrated ... from Abu al-Tufayl 'Amir ibn Wathila: I heard 'Ali ibn Abi Talib say to a man from Hadramawt: Have you seen a red dune mixed with red clods, with many arak and lote trees, in such and such part of the land of Hadramawt? ... He said: In it is the grave of Hud. ... This contains the benefit that their dwellings were in Yemen and that Hud was buried there.\""},{"ch":"thamud","w":"ابن كثير","bk":"ibnkathir","s":7,"ay":73,"x":"قَالَ عُلَمَاءُ التَّفْسِيرِ وَالنَّسَبِ: ثَمُودُ بْنُ عَاثِرَ بْنِ إِرَمَ بْنِ سَامَ بْنِ نُوحٍ، وَهُوَ أَخُو جَديس بْنِ عَاثِرَ، وَكَذَلِكَ قَبِيلَةُ طَسْم، كُلُّ هَؤُلَاءِ كَانُوا أَحْيَاءً مِنَ الْعَرَبِ الْعَارِبَةِ قَبْلَ إِبْرَاهِيمَ الْخَلِيلِ، عَلَيْهِ السَّلَامُ، وَكَانَتْ ثَمُودُ بَعْدَ عَادٍ، وَمَسَاكِنُهُمْ مَشْهُورَةٌ فِيمَا بَيْنَ الْحِجَازِ وَالشَّامِ إِلَى وَادِي الْقُرَى وَمَا حَوْلَهُ، وَقَدْ مَرَّ رَسُولُ اللَّهِ ﷺ عَلَى قُرَاهُمْ وَمَسَاكِنِهِمْ، وَهُوَ ذَاهِبٌ إِلَى تَبُوكَ سَنَةَ تِسْعٍ","n":"نسب ثمود ومساكنهم بين الحجاز والشام، ومرور النبي ﷺ بها وهو ذاهب إلى تبوك.","en":"\"The scholars of tafsir and genealogy said: Thamud is the son of 'Athir ibn Iram ibn Sam ibn Nuh ... all of these were tribes of the original Arabs before Ibrahim, and Thamud came after 'Ad; their dwellings are well known between the Hijaz and the Levant up to Wadi al-Qura and what surrounds it, and the Messenger of God ﷺ passed by their villages and dwellings while going to Tabuk in the year nine.\""},{"ch":"thamud","w":"السعدي","bk":"saadi","s":7,"ay":73,"x":"واذۡكُروا إذ جَعَلَكُم خلفاءَ: في الأرض تتمتَّعون بها وتدركون مطالبكم، {من بعد عادٍ}: الذين أهلكهم الله وجعَلَكم خلفاء من بعدهم، {وبوَّأكم في الأرض}؛ أي: مكَّن لكم فيها وسهَّل لكم الأسباب الموصلة إلى ما تريدون وتبتغون، {تتَّخذونَ من سهولها قصوراً}؛ أي: الأراضي السهلة التي ليست بجبال بيوتاً، ومن الجبال بيوتاً ينحتونها كما هو مشاهدٌ إلى الآن أعمالهم التي في الجبال من المساكن والحِجْر ونحوها، وهي باقية ما بقيت الجبال","n":"يصف عمرانهم: قصور في السهول وبيوت منحوتة في الجبال لا تزال آثارها.","en":"\"And remember when He made you successors: on the earth you enjoy it and attain your needs, after 'Ad whom God destroyed, and He settled you in the land, that is: He established you in it and eased for you the means leading to what you want. You take palaces from its plains: the easy lands, not mountains, as homes, and from the mountains homes you carve, as is witnessed even now in their works in the mountains of dwellings and al-Hijr and the like, which remain as long as the mountains remain.\""},{"ch":"thamud","w":"ابن كثير","bk":"ibnkathir","s":15,"ay":80,"x":"أَيْ: مِنْ غَيْرِ خَوْفٍ وَلَا احْتِيَاجٍ إِلَيْهَا، بَلْ أَشَرًا وَبَطَرًا وَعَبَثًا","n":"ينبّه إلى أن نحتهم لم يكن لحاجة بل للمباهاة والعبث.","en":"\"That is: without fear and without need of them, but out of arrogance, insolence and futility.\""},{"ch":"lut","w":"السعدي","bk":"saadi","s":7,"ay":80,"x":"وينهاهم عن الفاحشة التي ما سبقَهم بها أحدٌ من العالمين؛ فقال:{أتأتونَ الفاحشةَ}؛ أي: الخصلة التي بلغت في العِظَم والشَّناعة إلى أن استغرقتْ أنواعَ الفحش، {ما سَبَقَكم بها من أحدٍ من العالمين}: فكونُها فاحشةً من أشنع الأشياء، وكونُهم ابتدعوها، وابتَكَروها، وسَنُّوها لمن بعدَهم من أشنع ما يكونُ أيضاً","n":"ابتدعوا فاحشة وسنّوها لمن بعدهم، وكان ذلك من أشنع الأمور.","en":"\"And forbids them the indecency which no one among the worlds preceded them in: ... for it being an indecency is among the most hideous things, and their having innovated it and initiated it and made it a custom for those after them is also among the most hideous things.\""},{"ch":"lut","w":"ابن كثير","bk":"ibnkathir","s":7,"ay":80,"x":"وَلُوطٌ هُوَ ابْنُ هَارَانَ بْنِ آزَرَ، وَهُوَ ابْنُ أَخِي إِبْرَاهِيمَ الْخَلِيلِ، عَلَيْهِمَا السَّلَامُ، وَكَانَ قَدْ آمَنَ مَعَ إِبْرَاهِيمَ، عَلَيْهِ السَّلَامُ، وَهَاجَرَ مَعَهُ إِلَى أَرْضِ الشَّامِ، فَبَعَثَهُ اللَّهُ [تَعَالَى] إِلَى أهل \"سَدُوم\" وما حَوْلَهَا مِنَ الْقُرَى","n":"نسب لوط وهجرته مع إبراهيم وبعثته إلى سدوم.","en":"\"Lut is the son of Haran ibn Azar, the nephew of Ibrahim the Intimate Friend, peace be upon both, and he had believed with Ibrahim and migrated with him to the land of the Levant; then God sent him to the people of 'Sodom' and what surrounds it of villages.\""},{"ch":"madyan","w":"السعدي","bk":"saadi","s":7,"ay":85,"x":"أرسلنا إلى القبيلة المعروفة بمدين {أخاهم}: في النسب، {شُعَيۡباً}: يدعوهم إلى عبادة الله وحده لا شريك له، ويأمرهم بإيفاء المكيال والميزان، وأن لا يبخسوا الناس أشياءهم، وأن لا يعثَوْا في الأرض مفسدين بالإكثار من عمل المعاصي","n":"رسالة شعيب: توحيد وعدل في الميزان وترك الإفساد.","en":"\"We sent to the tribe known as Madyan their brother in lineage, Shu'ayb, calling them to worship God alone with no partner, and ordering them to give full measure and weight, not to deprive people of their things, and not to spread corruption in the land by multiplying acts of disobedience.\""},{"ch":"madyan","w":"ابن كثير","bk":"ibnkathir","s":26,"ay":176,"x":"هَؤُلَاءِ -أَعْنِي أَصْحَابَ الْأَيْكَةِ -هُمْ أَهْلُ مَدْيَنَ عَلَى الصَّحِيحِ. وَكَانَ نَبِيُّ اللَّهِ شُعَيْبٌ مِنْ أَنْفُسِهِمْ، وَإِنَّمَا لَمْ يَقُلْ هُنَا أَخُوهُمْ شُعَيْبٌ؛ لِأَنَّهُمْ نُسِبُوا إِلَى عِبَادَةِ الْأَيْكَةِ، وَهِيَ شَجَرَةٌ","n":"يرجّح أن أصحاب الأيكة هم أهل مدين، ويفسّر عدم قول «أخوهم».","en":"\"These, I mean the people of the Thicket, are the people of Madyan on the sounder view. And the prophet of God Shu'ayb was of them, but it was not said here 'their brother Shu'ayb' because they were attributed to worship of the Thicket, which is a tree.\""},{"ch":"rass","w":"ابن كثير","bk":"ibnkathir","s":25,"ay":38,"x":"وَأَمَّا أَصْحَابُ الرَّسِّ فَقَالَ ابْنُ جُرَيْج، عَنِ ابْنِ عَبَّاسٍ: هُمْ أَهْلُ قَرْيَةٍ مِنْ قُرَى ثَمُودَ. وَقَالَ ابْنُ جُرَيْجٍ: قَالَ عِكْرِمَةُ: أَصْحَابُ الرَسّ بفَلَج وَهُمْ أَصْحَابُ يس. وَقَالَ قَتَادَةُ: فَلَج مِنْ قُرَى الْيَمَامَةِ","n":"يعرض اختلاف الصحابة والتابعين في تعيين أصحاب الرس.","en":"\"As for the Companions of ar-Rass, Ibn Jurayj said, from Ibn 'Abbas: They are the people of a village from the villages of Thamud. And Ibn Jurayj said: 'Ikrima said: The Companions of ar-Rass were at Falaj, and they are the people of Ya-Sin. And Qatada said: Falaj is one of the villages of al-Yamama.\""},{"ch":"firaun","w":"السعدي","bk":"saadi","s":28,"ay":4,"x":"إنَّ فرعون علا في الأرض: في ملكه وسلطانِهِ وجنودِهِ وجبروتِهِ، فصار من أهل العلوِّ فيها، لا من الأعْلَيْن فيها، {وجعل أهلها شِيَعاً}؛ أي: طوائف متفرِّقة يتصرَّف فيهم بشهوته وينفِّذ فيهم ما أراد من قهره وسطوته، {يستضعِفُ طائفةً منهم}: وتلك الطائفةُ هم بنو إسرائيل","n":"تفسير علوّ فرعون: ملك وجنود وجبروت، وتقسيم الناس شيعاً.","en":"\"Indeed Pharaoh exalted himself in the land: in his kingdom, authority, armies and tyranny, so he became of the people of arrogance in it, not of the higher ones; and made its people into factions, that is: scattered groups he dealt with by his whim and imposed on them what he wished of force and might, oppressing a group of them, and that group was the Children of Israel.\""},{"ch":"firaun","w":"السعدي","bk":"saadi","s":44,"ay":25,"x":"كم تركوا من جناتٍ وعيونٍ. وزروع ومقام كريم. ونعمةٍ كانوا فيها فاكهينَ. كذلك وأوۡرَثۡناها؛ أي: هذه النعمة المذكورة قوماً آخرينَ","n":"ما جمعوه من النعم ورثه قوم آخرون.","en":"\"'How many gardens and springs they left, and crops and noble dwellings, and favors in which they delighted. Thus, and We made it inherited by' that is: this blessing mentioned, 'another people.'\""},{"ch":"firaun","w":"السعدي","bk":"saadi","s":44,"ay":25,"x":"فما بكتۡ عليهم السماءُ والأرضُ؛ أي: لمَّا أتلفهم الله وأهلكهم لم تبكِ عليهم السماء والأرض؛ أي: لم يُحزنْ عليهم ولم يُؤس على فراقهم، بل كلٌّ استبشر بهلاكِهِم وتلفِهِم، حتى السماء والأرض؛ لأنَّهم ما خَلَّفوا من آثارِهم إلاَّ ما يسوِّدُ وجوهَهم ويوجبُ عليهم اللعنةَ والمقتَ من العالمين","n":"لم يخلّفوا إلا ما يسوّد وجوههم ويوجب اللعنة.","en":"\"'Neither heaven nor earth wept for them', that is: when God destroyed them neither heaven nor earth grieved for them nor regretted their parting; rather each rejoiced at their destruction, because they left of their traces nothing but what blackens their faces and incurs the curse and the abhorrence of all the worlds.\""},{"ch":"saba","w":"السعدي","bk":"saadi","s":34,"ay":15,"x":"سبأ قبيلةٌ معروفةٌ في أداني اليمن، ومسكنُهم بلدةٌ يُقالُ لها: مأرِب، ومن نعم الله ولطفِهِ بالناس عموماً وبالعرب خصوصاً أنه قصَّ في القرآن أخبار المهلكين والمعاقَبين ممَّنْ كان يجاوِرُ العرب، ويشاهدُ آثاره، ويتناقلُ الناس أخبارَه؛ ليكونَ ذلك أدعى إلى التصديق وأقربَ للموعظة، فقال:{لقد كان لسبأٍ في مسكنِهِم}؛ أي: محلِّهم الذي يسكنون فيه {آيةٌ}: والآيةُ هنا ما أدرَّ الله عليهم من النعم، وصرف عنهم من النقم، الذي يقتضي ذلك منهم أن يَعْبُدوا الله ويشكُروه","n":"يعرّف سبأ ومأرب، ويبيّن أن الآية نعمهم التي تقتضي الشكر.","en":"\"Saba is a well-known tribe in the nearer parts of Yemen, and their dwelling is a town called Marib ... 'There was for Saba in their dwelling a sign,' that is: in their place of residence 'a sign', and the sign here is what God poured upon them of blessings and turned away from them of calamities, which required of them to worship God and thank Him.\""},{"ch":"saba","w":"ابن كثير","bk":"ibnkathir","s":34,"ay":15,"x":"كَانَتْ سَبَأٌ ملوكَ الْيَمَنِ وَأَهْلَهَا، وَكَانَتِ التَّبَابِعَةُ مِنْهُمْ، وَبِلْقِيسُ -صَاحِبَةُ سُلَيْمَانَ-مِنْهُمْ ، وَكَانُوا فِي نِعْمَةٍ وَغِبْطَةٍ فِي بِلَادِهِمْ، وَعَيْشِهِمْ وَاتِّسَاعِ أَرْزَاقِهِمْ وَزُرُوعِهِمْ وَثِمَارِهِمْ. وَبَعَثَ اللَّهُ إِلَيْهِمُ الرُّسُلَ تَأْمُرُهُمْ أَنْ يَأْكُلُوا مِنْ رِزْقِهِ، وَيَشْكُرُوهُ بِتَوْحِيدِهِ وَعِبَادَتِهِ، فَكَانُوا كَذَلِكَ مَا شَاءَ اللَّهُ ثُمَّ أَعْرَضُوا عَمَّا أُمِرُوا بِهِ، فَعُوقِبُوا بِإِرْسَالِ السَّيْلِ وَالتَّفَرُّقِ فِي الْبِلَادِ أَيْدِيَ سَبَأٍ، شَذَرَ مَذرَ","n":"يضع سبأ في سياق ملوك اليمن، ويذكر أن بلقيس منهم، وأن عقوبتهم السيل والتفرق.","en":"\"Saba were the kings of Yemen and its people, and the Tubba' were of them, and Bilqis, the companion of Sulayman, was of them; they lived in blessing and happiness in their land, in livelihood, wide provisions, crops and fruits. God sent messengers to them commanding them to eat of His provision and thank Him by monotheism and worship; so they were so for as long as God willed, then turned away from what they were commanded, so they were punished by the sending of the flood and by being scattered in the lands, the hands of Saba, in every direction.\""},{"ch":"dhulqarnayn","w":"السعدي","bk":"saadi","s":18,"ay":83,"x":"وهذه الأسبابُ التي أعطاه الله إيَّاها لم يُخْبِرْنا الله ولا رسولُهُ بها، ولم تتناقَلْها الأخبارُ على وجهٍ يفيدُ العلم؛ فلهذا لا يَسَعُنا غير السكوت عنها وعدم الالتفات لما يَذْكُرُهُ النقلة للإسرائيلياتِ ونحوها","n":"يمنع من تفصيل ما سكت عنه القرآن بالإسرائيليات.","en":"\"And these means that God gave him, neither God nor His Messenger told us of them, and reports did not convey them in a way that yields knowledge; so we have nothing but to be silent about them and not to turn to what the transmitters of Isra'iliyyat and the like mention.\""},{"ch":"dhulqarnayn","w":"السعدي","bk":"saadi","s":18,"ay":83,"x":"وهذا يدلُّ على كونه من الملوك الصالحين [و] الأولياء العادلين العالمين؛ حيث وافق مرضاةَ الله في معاملة كلِّ أحدٍ بما يليق بحاله","n":"يستنبط من سياسته العدل بين الكافر والمؤمن أنه من الملوك الصالحين.","en":"\"And this indicates that he was among the righteous kings, the just, knowing friends of God, as he conformed to God's pleasure in treating everyone in a manner befitting his state.\""},{"ch":"dhulqarnayn","w":"السعدي","bk":"saadi","s":18,"ay":93,"x":"وهما أمَّتان عظيمتان من بني آدم، فقالوا:{إنَّ يأجوج ومأجوجَ مفسدون في الأرض}: بالقتل وأخذ الأموال وغير ذلك","n":"يأجوج ومأجوج أمتان من بني آدم، وإفسادهما بالقتل وأخذ الأموال.","en":"\"And they are two great nations of the children of Adam, so they said: 'Indeed Yajuj and Majuj are corrupters in the land' by killing and taking property and other things.\""},{"ch":"ukhdud","w":"السعدي","bk":"saadi","s":85,"ay":4,"x":"وكان أصحابُ الأخدود هؤلاء قوماً كافرين، ولديهم قومٌ مؤمنون، فراودوهم على الدُّخول في دينهم، فامتنع المؤمنون من ذلك، فشقَّ الكافرون أخدوداً في الأرض، وقذفوا فيها النار، وقعدوا حولَها، وفتنوا المؤمنين، وعرضوهم عليها؛ فمن استجاب لهم أطلقوه، ومن استمرَّ على الإيمان قذفوه في النار","n":"يشرح قصة الأخدود: كفار يفتنون المؤمنين بالنار.","en":"\"And these companions of the trench were disbelieving people who had believing people with them; they tried to make them enter their religion and the believers refused, so the disbelievers dug a trench in the ground and threw fire into it and sat around it and tested the believers and presented them to it: whoever responded to them they released, and whoever persisted in faith they threw into the fire.\""},{"ch":"ukhdud","w":"السعدي","bk":"saadi","s":85,"ay":4,"x":"وهذا من أعظم ما يكون من التجبُّر وقساوة القلب؛ لأنَّهم جمعوا بين الكفر بآيات الله ومعاندتها ومحاربة أهلها وتعذيبهم بهذا العذاب الذي تَنْفَطِرُ منه القلوب وحضورهم إيَّاهم عند إلقائهم فيها","n":"يبيّن أن الجريمة جمعت الكفر والمحاربة والتعذيب والحضور.","en":"\"And this is among the greatest forms of tyranny and hardness of heart, for they combined disbelief in God's signs and obstinacy toward them with fighting its people and torturing them with this torment from which hearts rend, and their presence at the time of their being thrown into it.\""},{"ch":"tubba","w":"السعدي","bk":"saadi","s":50,"ay":12,"x":"وقوم تُبَّعٍ ـ وتُبَّعٌ كل ملكٍ مَلَكَ اليمن في الزمان السابق قبل الإسلام ـ فقوم تُبَّع كذَّبوا الرسول الذي أرسله الله إليهم، ولم يخبرْنا اللهُ من هو ذلك الرسولُ، وأيُّ تُبَّعٍ من التَّبابعة","n":"يعرّف تُبّعاً بأنه لقب ملوك اليمن، ويصرّح بأن القرآن لم يعيّن أيّهم.","en":"\"And the people of Tubba' - and Tubba' is every king who ruled Yemen in the earlier time before Islam - so the people of Tubba' denied the messenger God sent to them, and God did not tell us who that messenger is, nor which Tubba' of the Tubba' kings.\""},{"ch":"tubba","w":"ابن كثير","bk":"ibnkathir","s":44,"ay":37,"x":"وَكَقَوْمِ تُبَّعٍ -وَهُمْ سَبَأٌ-حَيْثُ أَهْلَكَهُمُ اللَّهُ وخَرَّب بِلَادَهُمْ، وَشَرَّدَهُمْ فِي الْبِلَادِ، وَفَرَّقَهُمْ شَذَرَ مَذَرَ","n":"يربط قوم تبع بسبأ في العقوبة والتشتيت.","en":"\"And like the people of Tubba' - and they are Saba' - when God destroyed them and ruined their lands, scattered them in the lands, and dispersed them in all directions.\""},{"ch":"rum","w":"السعدي","bk":"saadi","s":30,"ay":2,"x":"كانت الفرس والروم في ذلك الوقت من أقوى دول الأرض، وكان يكون بينهما من الحروب والقتال ما يكون بين الدول المتوازنة، وكانتِ الفرسُ مشركينَ يعبُدون النار، وكانت الرومُ أهلَ كتابٍ ينتسبون إلى التوراة والإنجيل، وهم أقربُ إلى المسلمين من الفرس، [فكان المؤمنون] يحبُّون غَلَبَتَهم وظهورَهم على الفرس، وكان المشركون لاشتراكِهِم والفرسُ في الشرك يحبُّون ظهورَ الفرس على الروم، فظهر الفرسُ على الروم وغلبوهم غُلباً لم يُحِطْ بِمُلْكِهِم بل بأدنى أرضهم، ففرح بذلك مشركو مكة وحزن المسلمون","n":"سياق الآيات: دولتان عظيمتان، وفرح المشركين بغلبة الفرس وحزن المسلمين.","en":"\"The Persians and the Romans at that time were among the strongest states on earth ... the Persians were idolaters worshipping fire, and the Romans were People of the Book ... so the believers loved their victory over the Persians, and the idolaters, for their shared shirk with the Persians, loved the Persians' victory over the Romans; so the Persians defeated the Romans ... and the idolaters of Makkah rejoiced and the Muslims grieved.\""},{"ch":"rum","w":"ابن كثير","bk":"ibnkathir","s":30,"ay":1,"x":"هَذِهِ الْآيَاتُ حِينَ غَلَبَ سَابُورُ مَلِكُ الْفُرْسِ عَلَى بِلَادِ الشَّامِ وَمَا وَالَاهَا مِنْ بِلَادِ الْجَزِيرَةِ وَأَقَاصِي بِلَادِ الرُّومِ، وَاضْطَرَّ هِرَقْلَ مَلك الرُّومِ حَتَّى أَلْجَأَهُ إِلَى الْقُسْطَنْطِينِيَّةِ","n":"يروي ظرف النزول: غلبة سابور على بلاد الشام واضطرار هرقل إلى القسطنطينية.","en":"\"These verses were revealed when Sabur, king of the Persians, prevailed over the lands of the Levant and what adjoined them of the lands of the Peninsula and the farthest lands of the Romans, and forced Heraclius, king of the Romans, until he drove him to Constantinople.\""},{"ch":"israel","w":"السعدي","bk":"saadi","s":17,"ay":4,"x":"وقَضَيۡنا إلى بني إسرائيل؛ أي: تقدَّمنا وعَهِدْنا إليهم وأخبرناهم في كتابهم أنهم لا بدَّ أن يقعَ: منهم إفسادٌ في الأرض مرتين بعمل المعاصي والبَطَر لنعم الله والعلوِّ في الأرض والتكبُّر فيها، وأنَّه إذا وقع واحدةٌ منهما؛ سلَّطَ الله عليهم الأعداء وانتقم منهم، وهذا تحذيرٌ لهم وإنذارٌ لعلَّهم يرجعون فيتذكَّرون","n":"يفسر قضاء الإفسادين وتسليط الأعداء بأنه تحذير وإنذار.","en":"\"'And We decreed to the Children of Israel' that is: We gave advance notice and made a covenant with them, informing them in their book that there must occur from them corruption in the land twice by committing sins, insolence toward God's favors, arrogance and pride on earth; and that when one of them occurs God would give enemies power over them and take revenge from them. This is a warning and notice that they may return and remember.\""},{"ch":"israel","w":"السعدي","bk":"saadi","s":44,"ay":25,"x":"ولقد اختَرۡناهم؛ أي: اصطفيناهم وانتَقَيْناهم {على علم}: منَّا بهم وباستحقاقهم لذلك الفضل {على العالَمين}؛ أي: عالمي زمانهم ومَنْ قبلهم وبعدَهم، حتى أتى اللهُ بأمة محمدٍ - صلى الله عليه وسلم - ففضَلوا العالمينَ كلَّهم، وجعلهم الله خير أمَّة أخرجت للناس، وامتنَّ عليهم بما لم يمتنَّ به على غيرهم","n":"يوضح معنى تفضيلهم على العالمين: عالمي زمانهم، ثم فُضّلت أمة محمد ﷺ.","en":"\"'And We chose them' that is: We selected and picked them 'knowingly' from Us of them and of their deservingness of that favor 'over the worlds' that is: the worlds of their time and those before and after them, until God brought the nation of Muhammad ﷺ and they surpassed all the worlds, and God made them the best nation brought out for mankind, and favored them with what He did not favor others.\""},{"ch":"fil","w":"السعدي","bk":"saadi","s":105,"ay":1,"x":"الذين كادوا بيتَه الحرام، وأرادوا إخرابه؛ فتجهَّزوا لأجل ذلك، واستصحبوا معهم الفِيَلَةَ لهدمه، وجاؤوا بجمعٍ لا قِبَلَ للعرب به من الحبشة واليمن، فلما انتهَوْا إلى قربِ مكَّةَ ـ ولم يكن بالعرب مدافعةٌ، وخرج أهل مكَّة من مكَّة خوفاً [على أنفسهم] منهم ـ أرسل الله عليهم طيراً أبابيلَ؛ أي: متفرِّقة، تحمل أحجاراً محمَّاة من سِجِّيلٍ، فرمتْهم بها، وتتبَّعَتْ قاصِيَهم ودانِيَهم، فخمدوا وهمدوا، وصاروا كعصفٍ مأكولٍ، وكفى الله شرَّهم، وردَّ كيدهم في نحورهم","n":"وصف الحدث: جمع من الحبشة واليمن بالفيلة ثم طير أبابيل بحجارة من سجيل.","en":"\"Those who plotted against His Sacred House and wanted to ruin it; so they prepared for that and brought elephants with them to demolish it, and came with a host the Arabs had no power against, from Abyssinia and Yemen; when they reached near Makkah ... God sent upon them flocks of birds carrying hot stones of baked clay and they pelted them with them, pursuing the far and near, so they became still and silent and were like eaten straw, and God sufficed against their evil and turned their plot back into their throats.\""},{"ch":"fil","w":"ابن كثير","bk":"ibnkathir","s":105,"ay":1,"x":"وَكَانُوا قَوْمًا نَصَارَى، وَكَانَ دِينُهُمْ إِذْ ذَاكَ أَقْرَبَ حَالًا مِمَّا كَانَ عَلَيْهِ قُرَيْشٌ مِنْ عِبَادَةِ الْأَوْثَانِ. وَلَكِنْ كَانَ هَذَا مِنْ بَابِ الْإِرْهَاصِ وَالتَّوْطِئَةِ لِمَبْعَثِ رَسُولُ اللَّهِ ﷺ","n":"يبين أن النصر على أصحاب الفيل لم يكن لخيرية قريش بل لحفظ البيت قبل بعثة النبي ﷺ.","en":"\"And they were a Christian people, and their religion at that time was closer in state than what Quraysh were upon of idol worship. But this was by way of a prelude and preparation for the mission of the Messenger of God ﷺ.\""}],"u":[{"id":"iram","t":"موضع إرم وديار عاد","n":"نصّ المفسرون على أن عاداً سكنوا الأحقاف باليمن (ابن كثير والسعدي). أما ربط إرم بمدينة مدفونة معيّنة اكتُشفت أو ادُّعي اكتشافها فاجتهاد حديث غير جازم، ولم يرد فيه نص."},{"id":"pharaoh","t":"اسم فرعون موسى وعصره","n":"لم يسمِّ القرآن فرعون موسى ولا حدّد زمنه. وتعيينه بملك مصري بعينه، أو بتاريخ بعينه، اجتهاد من المؤرخين وعلماء الآثار غير جازم؛ والمقطوع به ما ورد في الآيات والأحاديث."},{"id":"dhulq","t":"من هو ذو القرنين؟","n":"اختلف المفسرون والمؤرخون في تعيينه، وأورد ابن كثير في تفسيره أقوالاً وحذّر مما لم يصح منها. وقد قال السعدي إن الأسباب التي أُعطيها لم يخبرنا الله ولا رسوله بها، ولا نلتفت للإسرائيليات. فكل تعيين لشخصه اجتهاد غير جازم."},{"id":"sadd","t":"موضع السد","n":"قال السعدي إن «السدين» جبلان معروفان في ذلك الزمان بين يأجوج ومأجوج والناس. أما تحديد موضع الردم على الخريطة اليوم فاجتهاد غير جازم؛ والثابت أن الله أقامه بقوة الحديد والقطر، وأنه سيُدكّ عند وعد الله."},{"id":"places","t":"أصحاب الأخدود وأصحاب الرس","n":"لم يعيّن القرآن موضعهم ولا زمنهم. وفي أصحاب الرس أقوال متباينة نقلها ابن كثير: قرية من قرى ثمود، وفلج باليمامة، وبئر بأذربيجان. فلا نجزم بشيء منها."},{"id":"ages","t":"الأعمار والمدد","n":"ما نصّ عليه القرآن: لبث نوح في قومه ألف سنة إلا خمسين عاماً (العنكبوت: ١٤)، ومدة غلبة الروم «بضع سنين» (الروم: ٤). وما سوى ذلك من تقدير الأعمار والمدد بالتواريخ الدقيقة اجتهاد غير جازم."}],"ay":{"53":"يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ","54":"وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ","55":"وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ","56":"وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ","252":"أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ","253":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","254":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","255":"فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ","256":"وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","257":"فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ","688":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ","689":"يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ","690":"قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ","691":"قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ","692":"قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ","693":"قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ","694":"قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ","746":"لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","747":"كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ","1018":"۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ","1019":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ","1020":"قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","1021":"أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ","1022":"أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ","1026":"وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ","1027":"وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1028":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ","1029":"قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ","1030":"فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ","1031":"فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ","1032":"فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ","1033":"وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ","1034":"إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ","1035":"وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ","1036":"فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ","1037":"وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ","1038":"وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","1039":"وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ","1040":"وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ","1041":"۞ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ","1042":"قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ","1043":"وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ","1044":"فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ","1045":"ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ","1046":"فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ","1090":"وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ","1453":"۞ وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ","1454":"ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ","1455":"فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ","1497":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","1498":"أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ","1499":"فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ","1509":"وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","1510":"وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ","1511":"فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ","1512":"حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ","1513":"۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ","1514":"وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ","1515":"قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ","1516":"وَقِيلَ يَٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ","1517":"وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ","1518":"قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ","1519":"قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ","1533":"۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ","1534":"قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ","1535":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ","1536":"وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ","1537":"فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ","1538":"فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ","1539":"وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ","1540":"كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ","1549":"وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ","1550":"وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ","1551":"قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ","1552":"قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ","1553":"قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ","1554":"فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ","1555":"مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ","1561":"وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ","1562":"وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ","1563":"قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ","1564":"قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ","1565":"وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ","1566":"وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ","1567":"كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ","1589":"وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ","1704":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ","1706":"لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ","1874":"فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ","1875":"فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ","1876":"إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ","1877":"وَإِنَّهَا لَبِسَبِيلٖ مُّقِيمٍ","1878":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ","1879":"وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ","1880":"فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ","1881":"وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ","1882":"وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ","1883":"وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ","1884":"فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ","1885":"فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ","2032":"وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا","2033":"فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا","2034":"ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا","2035":"إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا","2036":"عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا","2044":"وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا","2222":"وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا","2223":"إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا","2224":"فَأَتۡبَعَ سَبَبًا","2225":"حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا","2226":"قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا","2227":"وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا","2228":"ثُمَّ أَتۡبَعَ سَبَبًا","2229":"حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا","2230":"كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا","2231":"ثُمَّ أَتۡبَعَ سَبَبًا","2232":"حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا","2233":"قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا","2234":"قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا","2235":"ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا","2236":"فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا","2237":"قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا","2578":"حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ","2579":"وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ","2892":"وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا","2893":"وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا","2894":"وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا","2988":"فَأَخۡرَجۡنَٰهُم مِّن جَنَّٰتٖ وَعُيُونٖ","2989":"وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ","2990":"كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَٰٓءِيلَ","3059":"أَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ","3060":"وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ","3061":"وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ","3062":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","3063":"وَٱتَّقُواْ ٱلَّذِيٓ أَمَدَّكُم بِمَا تَعۡلَمُونَ","3064":"أَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ","3065":"وَجَنَّٰتٖ وَعُيُونٍ","3066":"إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ","3077":"أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ","3078":"فِي جَنَّٰتٖ وَعُيُونٖ","3079":"وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ","3080":"وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ","3107":"كَذَّبَ أَصۡحَٰبُ لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ","3108":"إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ","3109":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3110":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","3111":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","3112":"۞ أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ","3113":"وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ","3114":"وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","3115":"وَٱتَّقُواْ ٱلَّذِي خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ","3116":"قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ","3117":"وَمَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَٰذِبِينَ","3118":"فَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","3119":"قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ","3120":"فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ","3121":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","3122":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","3180":"فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ","3181":"إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ","3182":"وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ","3183":"أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ","3184":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩","3187":"قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ","3188":"إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","3189":"أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ","3190":"قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ","3191":"قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ","3192":"قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ","3193":"وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ","3202":"قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","3212":"وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ","3213":"أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ تَجۡهَلُونَ","3214":"۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطٖ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ","3215":"فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ","3216":"وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ","3255":"إِنَّ فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعٗا يَسۡتَضۡعِفُ طَآئِفَةٗ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِينَ","3256":"وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةٗ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ","3257":"وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ","3289":"وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ","3310":"وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولٗا يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ","3353":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ","3354":"فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ","3409":"الٓمٓ","3410":"غُلِبَتِ ٱلرُّومُ","3411":"فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ","3412":"فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ","3413":"بِنَصۡرِ ٱللَّهِۚ يَنصُرُ مَن يَشَآءُۖ وَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","3414":"وَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","3415":"يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ","3417":"أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","3418":"ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا يَسۡتَهۡزِءُونَ","3620":"لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ","3621":"فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ","3622":"ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ","3623":"وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرٗى ظَٰهِرَةٗ وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ","3624":"فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ","4232":"فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ","4233":"فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ","4375":"وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ","4376":"أَمۡ أَنَا۠ خَيۡرٞ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينٞ وَلَا يَكَادُ يُبِينُ","4377":"فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ","4378":"فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ","4379":"فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ","4380":"فَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ","4438":"كَمۡ تَرَكُواْ مِن جَنَّٰتٖ وَعُيُونٖ","4439":"وَزُرُوعٖ وَمَقَامٖ كَرِيمٖ","4440":"وَنَعۡمَةٖ كَانُواْ فِيهَا فَٰكِهِينَ","4441":"كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ","4442":"فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ","4450":"أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ","4530":"۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ","4531":"قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","4532":"قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ","4533":"فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ","4534":"تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ","4535":"وَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","4641":"كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ","4642":"وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ","4643":"وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ","4854":"۞ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونٞ وَٱزۡدُجِرَ","4855":"فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ","4856":"فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءٖ مُّنۡهَمِرٖ","4857":"وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرٖ قَدۡ قُدِرَ","4858":"وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحٖ وَدُسُرٖ","4859":"تَجۡرِي بِأَعۡيُنِنَا جَزَآءٗ لِّمَن كَانَ كُفِرَ","4860":"وَلَقَد تَّرَكۡنَٰهَآ ءَايَةٗ فَهَلۡ مِن مُّدَّكِرٖ","4863":"كَذَّبَتۡ عَادٞ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","4864":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِي يَوۡمِ نَحۡسٖ مُّسۡتَمِرّٖ","4865":"تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٖ مُّنقَعِرٖ","4868":"كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ","4869":"فَقَالُوٓاْ أَبَشَرٗا مِّنَّا وَٰحِدٗا نَّتَّبِعُهُۥٓ إِنَّآ إِذٗا لَّفِي ضَلَٰلٖ وَسُعُرٍ","4870":"أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٞ","4871":"سَيَعۡلَمُونَ غَدٗا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ","4872":"إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ","4873":"وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ","4874":"فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ","4875":"فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","4876":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةٗ وَٰحِدَةٗ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ","4878":"كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ","4879":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطٖۖ نَّجَّيۡنَٰهُم بِسَحَرٖ","4880":"نِّعۡمَةٗ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ","4881":"وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ","4882":"وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ عَذَابِي وَنُذُرِ","4883":"وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابٞ مُّسۡتَقِرّٞ","4884":"فَذُوقُواْ عَذَابِي وَنُذُرِ","5239":"وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","5328":"وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ","5329":"سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ","5330":"فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ","5423":"قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا","5424":"فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا","5425":"وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا","5426":"ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا","5427":"ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا","5912":"قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ","5913":"ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ","5914":"إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ","5915":"وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ","5916":"وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ","5917":"ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","5918":"إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ","5919":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ","5925":"هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ","5926":"فِرۡعَوۡنَ وَثَمُودَ","5927":"بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ","5928":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ","5998":"أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ","5999":"إِرَمَ ذَاتِ ٱلۡعِمَادِ","6000":"ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ","6053":"كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","6054":"إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","6055":"فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","6056":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","6057":"وَلَا يَخَافُ عُقۡبَٰهَا","6188":"أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ","6189":"أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ","6190":"وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ","6191":"تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","6192":"فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ","6193":"لِإِيلَٰفِ قُرَيۡشٍ","6194":"إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ","6195":"فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","6196":"ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ"},"nay":290};
